func HasTopUpOrdersWith(preds ...predicate.TopUpOrder) predicate.User {
	return predicate.User(func(s *sql.Selector) {
		step := newTopUpOrdersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

